import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"UniTemp: Unlocking Video Generation in Any Temporal Order via Bidirectional Distillation","description":"","frontmatter":{"title":"UniTemp: Unlocking Video Generation in Any Temporal Order via Bidirectional Distillation","arxiv":"2606.18702","date":"2026-06-17","authors":"Lin Zhang, Sicheng Mo, Zefan Cai, Jinhong Lin, Zihao Lin, Jiuxiang Gu, Krishna Kumar Singh, Yuheng Li, Yin Li","categories":"cs.CV","topics":"自回归视频生成, 双向蒸馏, 中间帧生成","outline":[2,2]},"headers":[],"relativePath":"papers/2606.18702.md","filePath":"papers/2606.18702.md","lastUpdated":null}'),l={name:"papers/2606.18702.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="unitemp-unlocking-video-generation-in-any-temporal-order-via-bidirectional-distillation" tabindex="-1">UniTemp: Unlocking Video Generation in Any Temporal Order via Bidirectional Distillation <a class="header-anchor" href="#unitemp-unlocking-video-generation-in-any-temporal-order-via-bidirectional-distillation" aria-label="Permalink to &quot;UniTemp: Unlocking Video Generation in Any Temporal Order via Bidirectional Distillation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.18702" target="_blank" rel="noreferrer">2606.18702</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-17</td></tr><tr><td><strong>作者</strong></td><td>Lin Zhang, Sicheng Mo, Zefan Cai, Jinhong Lin, Zihao Lin, Jiuxiang Gu, Krishna Kumar Singh, Yuheng Li, Yin Li（威斯康星麦迪逊 + Adobe Research + UCLA + UC Davis）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>在同一次 Self-Forcing 蒸馏里同时训练正序与倒序 rollout，并在每个倒序块前额外联合去噪 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 个「锚点潜变量」来补上 Causal 3D VAE 缺失的过去上下文、推理时丢弃它们，从而用一个学生模型支持任意时间方向与中间填充。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/autoregressive">自回归视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>自回归视频扩散已经能做流式长视频，但它只会<strong>往前</strong>生成。真实的创作流程不是这样：给已有片段补一段前情（向后扩展）、在两段之间填空（inbetween）、先定几个关键场景再把它们连成故事——这些都要求灵活的时间顺序。现有方案各自只覆盖一种模式：MCVD 沿通道拼接过去与未来帧并随机遮蔽，RaMViD 随机遮蔽帧子集，VACE 用输入视频掩码统一大量生成与编辑任务。它们都需要全序列去噪加上复杂的输入格式，推理慢；而且要么需要海量真实视频预训练，要么需要微调。</p><p>论文要回答的是：能不能训练<strong>一个</strong>自回归模型，在测试时任意选择以过去、以未来、或以两者为条件，并保持实时速度。</p><p>真正卡住这件事的不是生成器，而是<strong>tokenizer</strong>。现代视频扩散几乎全用 Causal 3D VAE——每个 latent 的编码与解码都只依赖它的过去上下文。这个设计带来统一的图像/视频 tokenization、更好的生成质量和更低的显存，被 CogVideoX、Cosmos、HunyuanVideo、Wan 全线采用。但它对生成方向施加了一个<strong>不对称的先验</strong>：正序生成时每个 latent 都能拿到它被编码时所依赖的那段过去，倒序生成时拿不到。重训一个非因果 VAE 不现实——那会丢掉与所有已有教师模型的兼容性。这个约束此前几乎没被研究过，因为在只往前走的世界里它从不显形。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>灵活条件一支。</strong> MCVD / RaMViD / VACE 用掩码引导的 inpainting 加全序列 attention 实现任意位置条件。它们的问题是三重的：全序列去噪导致推理慢（论文表 7 里 VACE 只有 0.07–0.08 FPS、首帧延迟 157–161 秒）；输入格式复杂且有冗余特征提取；训练需要大规模真实视频。</p><p><strong>蒸馏式自回归一支。</strong> CausVid 首创非对称蒸馏，把多步全注意力教师压成少步自回归学生，配 KV cache 实现流式；Self-Forcing 让学生以自己的 rollout 而非真值为条件，大幅缓解长程退化；后续 LongLive、Rolling Forcing、Reward Forcing、Self-Forcing++（训练侧）与 Infinity-RoPE、Infinite-Forcing、Deep Forcing（免训练侧）继续稳定长生成。<strong>这些方法无一例外只支持正序</strong>。</p><p><strong>Causal VAE 一支。</strong> 论文的定位很准确：因果 3D VAE 的时间偏置「在此前工作中没有被很好地研究」，因为它只在生成方向反转时才成为障碍。相邻工作里最接近的是 Generative Inbetweening（GI），它在 Stable Video Diffusion 上微调出一个<strong>独立的反向图生视频分支</strong>，推理时正反各跑一遍完整去噪再加权融合——这既贵（表 7 里 295.7 秒）又只支持单端单帧条件。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是最朴素的尝试：既然 Self-Forcing 能训正序，把块生成顺序反过来不就能训倒序吗？做了之后发现视频闪烁严重，而且<strong>周期性地出现在块边界</strong>，表现为覆盖全画面的重影/闪光，高运动区域更明显。周期性 + 与块边界对齐，说明这不是随机噪声，而是结构性的。</p><p>第二步是找一个能定位问题的度量。VBench 的 temporal flickering 不行：它在整段视频上平均帧间像素差，看不出闪烁发生在<strong>哪里</strong>；而且它受视频动态程度严重影响，动得越猛分越低。于是需要一个局部的、对动态归一化的量——把「跨 latent 边界的像素差」除以「同一 latent 内部的像素差」，后者天然刻画了该处的局部动态强度。</p><p>第三步是用这个度量做诊断。测出来：正序的 inter-block FR 是 1.15、intra-block 是 0.93；倒序的 inter-block 飙到 1.42、intra-block 仍是 0.89。intra-block 在两个方向上都正常，说明块<strong>内部</strong>没问题——块内是全序列自注意力，每个 latent 都能看到块内在它之前的那些。异常只在块<strong>边界</strong>。这条对比直接指向 Causal 3D VAE：块内的 latent 有局部过去上下文，块首的 latent 在倒序时没有。</p><p>第四步是设计修法。既然缺的是「块首那个 latent 的过去上下文」，那就造一个代理：把块从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 扩到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>，前面 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span> 个是辅助的「锚点潜变量」，与目标块一起联合去噪。它们自己也缺过去上下文，所以去噪完直接丢掉、不进输出。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>倒序生成的闪烁不是生成器的错，是 tokenizer 的错：Causal 3D VAE 把每个 latent 编码成「以我的过去为条件」的形式，所以解码器在块边界处期待一段过去，而倒着生成时那段过去还不存在。解决办法不是重训 VAE，而是在每个倒序块前面临时造出几个「假的过去」陪着一起去噪，让块首的 latent 有东西可依，去噪完就扔掉。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>教师是 Wan2.1-T2V-14B，学生是从 Wan2.1-T2V-1.3B 初始化的 4 步模型（时间步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1000.0/937.5/833.3/625.0</span></span></span></span>），正序块大小 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span>，倒序锚点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span>。</p><p><strong>Stage-1（ODE 初始化）。</strong> 教师生成 16K 条 ODE 轨迹对（timestep shift 5.0、CFG 3.0，prompt 来自 VidProm），学生回归干净目标，batch 128、6K 迭代、8×8 张 H100/A100。<strong>每次迭代同时施加正序与倒序注意力掩码</strong>。这里有一个必须处理的歧义：正序的第一个块是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是特殊的图像 latent，倒序的第一个块是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">18</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">19</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">20</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 全是视频 latent，RoPE 对两者一视同仁，模型会分不清。基线的解法是在倒序时额外采一个不计损失的 dummy 块；而一旦用了锚点（块变成 6 个 latent），块长度本身就区分开了，dummy 块不再需要。</p><p><strong>Stage-2（DMD）。</strong> 学生按推理时的块自回归 rollout 生成，DMD 损失作用在<strong>整段</strong>生成序列上；真实分数网络仍是冻结的 Wan2.1-14B。batch 64、600 迭代，生成器 lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span></span>、fake critic lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">7</span></span></span></span></span></span></span></span></span></span></span></span>，学生每 5 步更新一次、critic 每步更新。<strong>训练全程不用任何视频数据</strong>，只用 VidProm 的 prompt（Qwen2.5-7B-Instruct 改写）。由于学生的输出序列严格不含锚点，Stage-2 无法对锚点施加损失。</p><p><strong>统一模型。</strong> 可以为正序/倒序各训一个生成器、各训一个 fake critic，但那样显存和训练成本都更高，且分开的生成器<strong>丧失了测试时灵活条件的能力</strong>（比如 inbetween 需要同时看两端）。所以共享同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span></span></span></span></span></span></span></span> 与同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2683em;vertical-align:-0.3013em;"></span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fake</span></span></span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3013em;"><span></span></span></span></span></span></span></span></span></span>。</p><p><strong>测试时的三个能力。</strong></p><ul><li><strong>双端 sink latent</strong>：以往只能把 sink 放在过去位置；现在可以通过 RoPE 重索引把已生成的第二个块<strong>搬到未来位置</strong>，为正序生成模拟一个「未来 sink」，倒序则反过来。</li><li><strong>Inbetween</strong>：训练时块大小是 3（或含锚点的 6），但测试时块大小可以任意设，只要总注意力跨度不超过训练时的 21。给定 3 个头 latent 与 3 个尾 latent，先算它们的 KV cache（尾块额外注意头块的 cache，RoPE 索引之间留出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 帧的间隔），再让中间 15 个 latent 作为一个大块联合全序列自注意力，同时注意两端 cache。</li><li><strong>应用</strong>：把头部条件帧搬到未来再填中间，得到循环视频；头尾差异很大时得到场景转场；配合任意生成顺序可以先生成多个关键场景再前后扩展/中间填充，做长镜头视觉叙事。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>Flickering Ratio。</strong> 对相邻 latent <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>（分别解出帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span><span class="mord mathnormal mtight">i</span><span class="mord mtight">..4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">3</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">4..4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">7</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>），</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">FR</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.6976em;vertical-align:-1.1218em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.5758em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1864em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">h</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">3</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.8258em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1864em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">h</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">4</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">3</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.1218em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord">.</span></span></span></span></span></p><p>分子是跨 latent 边界的帧间 L1 距离，分母是<strong>同一个 latent 解出的两帧</strong>之间的 L1 距离。后者是局部动态强度的天然估计量（同一 latent 内不存在生成不连续性），所以这个比值把「跨界跳变」对「本地正常运动幅度」做了归一化。理想值是 1.0：边界处的变化与内部一样自然。这个构造干净地解决了 VBench temporal flickering 的两个缺陷——它是局部的，且对动态程度免疫。</p><p><strong>为什么 intra-block 正常而 inter-block 异常。</strong> Causal 3D VAE 以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mord">×</span></span></span></span> 时间压缩编码，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是编码首帧的特殊图像 latent，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0</span><span class="mclose">)</span></span></span></span> 编码连续四帧。每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的编解码都依赖 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6757em;vertical-align:-0.2452em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2452em;"><span></span></span></span></span></span></span></span></span></span>。块内用全序列自注意力，块中第二、三个 latent 分别拥有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 作为局部过去，因此倒序时块内 FR 仍低（0.89）；而块首的 latent 在倒序时唯一可用的条件是<strong>未来</strong>块的 KV cache，它被编码时所依赖的那段过去完全缺席，于是 FR 冲到 1.42。</p><p><strong>锚点的作用。</strong> 把块扩成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 后联合去噪，块内全序列注意力让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 拿到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 作为过去代理，同时整块仍注意未来 latent 的 KV cache 获取未来条件。锚点自身（尤其 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>）现在坐在块的左边界、仍然没有自己的过去，所以必须丢弃——这一点被实验直接验证：把锚点也计入输出，倒序 inter-block FR 从 1.07 反弹到 1.46。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：锚点能否修复倒序闪烁？</strong> 表 1：正序基线 inter/intra FR 为 1.15/0.93；倒序无锚点 1.42/0.89；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 得 1.26、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 得 1.23、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 得 <strong>1.07</strong>（intra 0.97）。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 时锚点提供了完整一个块的过去上下文，比值逼近理想的 1.0。若把锚点计入输出，无论怎么训都会反弹到 1.46–1.48。用户研究：200 次 A/B 比较，87% 偏好带锚点的版本，且用户判断与 FR 的一致率 80.5%。</p><p><strong>问题二：统一模型是否有代价？</strong> 表 2（5s，VBench）：分离 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> 与分离 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fake</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（即 Self-Forcing 基线）正序 Total 83.42；共享 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> 得 83.54；再共享 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fake</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 得 83.81。倒序侧分别是 84.26 / 83.96 / 84.23。作者的结论是分离模型不带来显著收益却更贵，且统一训练缩小了两个方向之间的差距。</p><p><strong>这里必须看表 8 的逐维数据。</strong> UniTemp-Forward 相对 Self-Forcing：subject consistency 95.94 vs 96.54、background consistency 95.15 vs 95.83、temporal flicker 97.67 vs 98.26、motion smoothness 97.85 vs 98.31、aesthetic 65.73 vs 66.10、image quality 69.34 vs 69.81——<strong>七个质量维度里有六个变差</strong>，而 dynamic degree 从 65.00 跳到 81.67。Quality 分从 84.47 升到 84.89 基本由这一项拉动。</p><p><strong>问题三：长视频。</strong> 表 3（10s/30s/100s，128 条 MovieGenBench prompt）。只用过去 sink 时，UniTemp 的 dynamic degree 是 81.25/92.97/87.50，远高于所有基线（LongLive 36.72、Rolling-Forcing 28.12、Infinity-Rope 64.06→55.47、Self-Forcing 64.06→62.50），代价是 subject consistency 从 95.40 掉到 93.95，低于 LongLive 的 96.48 与 Self-Forcing 的 96.14。开启双端 sink 后翻转：100s 的 subject consistency 升到 97.30（全表最高）、aesthetic 稳定在 62.30，但 dynamic degree 掉到 44.50。倒序方向呈现同样的模式。所以「双端 sink」实际上是一个<strong>动态-一致性的调节旋钮</strong>，不是纯增益。</p><p><strong>问题四：inbetween。</strong> 用 Wan2.1-T2V-14B 对 128 条 MovieGenBench prompt 生成 5s 视频作为真值，保留头 9 帧（3 个 latent）与尾 12 帧（3 个 latent）作条件。UniTemp 的 FVD 25.00 最好（Wan FLF2V 27.77、GI 34.66），FID 24.94 次于 Wan FLF2V 的 23.31；aesthetic 65.75 与 image quality 66.68 全表最高；Head 边界一致性 99.52 最高，Tail 98.16 低于 Wan FLF2V 的 98.52。作者诚实地说明了 Head 高的原因：UniTemp 直接复用条件帧的 latent、不需要重新生成它们，而两个基线都会重新生成条件帧。效率上 UniTemp 9.0 秒 / 1.3B，对 GI 的 295.7 秒 / 1.5B 与 Wan FLF2V 的 1966.3 秒 / 14B。</p><p><strong>问题五：吞吐代价。</strong> 表 7：UniTemp 正序 14.8 FPS，与 Self-Forcing 完全相同；开双端 sink 降到 13.6；倒序只有 9.3（双端 sink 时 8.6）——<strong>倒序因为要多去噪 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 个锚点，吞吐降约 37%</strong>。显存 19.18→21.11 GiB。训练侧统一模型 Stage-1/2 为 16/3.0 小时（每卡），高于纯正序的 11/1.5 小时。</p><p><strong>问题六：附录里最重要的一行。</strong> 表 5 的 EXP-3：一个<strong>训练时完全不用锚点</strong>、倒序块大小设为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 的基线，只要在<strong>推理时丢弃每块先生成的 3 个 latent</strong>，倒序 inter-block FR 就从 1.48 降到 <strong>1.08</strong>——与 UniTemp 的 1.07 几乎相同。作者自己指出了这一点，并据此给出锚点的第二种解读：它们的作用是让相邻块<strong>重叠</strong>，从而改善连续性。此外表 5 显示两个阶段必须一致（只在一个阶段用锚点会退化到 1.17 或 1.37），且 Stage-1 对锚点加损失反而变差（1.07→1.15）。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：自回归视频生成只会往前走，而真实创作需要向后扩展与中间填充；直接把 Self-Forcing 的块顺序反过来会产生与块边界对齐的周期性闪烁，根因是 Causal 3D VAE 把每个 latent 编码成依赖其过去的形式，倒序时那段过去不存在；UniTemp 在每个倒序块前联合去噪 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 个锚点潜变量作为过去代理、去噪后丢弃，把倒序 inter-block FR 从 1.42 压到 1.07；共享同一个学生与同一个 fake critic 同时训正倒两个方向，训练不需要任何视频数据，测试时可以任意组合过去/未来条件，解锁双向扩展、inbetween、循环视频、场景转场与视觉叙事；代价是倒序吞吐降约 37%，且正序质量的七个维度里六个略低于纯正序基线，总分靠 dynamic degree 大涨拉回。</p><p><strong>三句话版</strong>：倒序生成的闪烁是 tokenizer 的因果性造成的，不是生成器的问题；在倒序块前补几个即用即弃的锚点潜变量就能把边界跳变压回接近 1.0；一个学生同时学会两个方向后，任意时间顺序的生成变成 KV cache 的重新排列问题。</p><p><strong>一句话版</strong>：视频模型不会倒着生成，是因为它的 tokenizer 只会正着编码。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>锚点潜变量之所以有效，是因为它们近似了 Causal 3D VAE 缺失的过去上下文。</strong></p><p>论文的整个诊断链条（因果 VAE → 块首缺过去 → 边界闪烁 → 补过去代理）都押在这个语义解释上。但附录表 5 的 EXP-3 给出了一个几乎同样好的、<strong>不含任何训练改动</strong>的替代：倒序块设成 6 个 latent，推理时把先生成的 3 个丢掉，inter-block FR 得到 1.08，而完整 UniTemp 是 1.07。也就是说，训练进锚点机制相对「生成重叠块然后扔掉一半」的边际收益是 0.01 FR。</p><p>作者对此是坦诚的——他们明确把这条解读为「锚点让不同块的生成产生重叠，从而改善连续性」。但一旦接受这个解读，「因果 VAE」这个因就不再是必要的：块重叠是一种通用的边界平滑手段，对任何分块生成都有效，与 tokenizer 是否因果无关。</p><p>支持因果解释的证据只有一条：把锚点解码出来能看到它们「确实可以被解码成视频 latent」，作者据此说它们是过去 latent 的近似。这是弱证据——任何在合理 latent 流形上的向量都能被解码成看起来像视频的东西。真正能判定的实验（把同样的锚点/重叠机制施加到<strong>正序</strong>上）全文没有做：表 5 里正序 FR 在所有行都稳定在 1.13–1.17，因为锚点从未用于正序。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做，不需要训练，且直击 §9。</p><ul><li><strong>底座</strong>：公开的 Self-Forcing 1.3B 权重（纯正序），只改推理逻辑。</li><li><strong>实现 FR</strong>：按式 (4) 实现 inter/intra-block flickering ratio；用 LLM 生成 128 条高动态 prompt（与论文协议一致）。</li><li><strong>三个臂（全部正序）</strong>：(a) 原生 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 逐块生成；(b) <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 逐块生成，<strong>丢弃每块最后 3 个 latent</strong>（正序的「锚点」应当在块尾，因为正序缺的是未来上下文——若正序不缺任何上下文，这一臂不应有改善）；(c) <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 逐块生成，丢弃每块<strong>最前</strong> 3 个 latent（纯重叠，与因果性无关）。</li><li><strong>判据</strong>：若 (c) 把正序 inter-block FR 从 1.15 显著拉向 1.0，则「块重叠」是通用平滑机制，因果 VAE 解释就不是必要条件，UniTemp 的训练改动价值需要重新评估；若 (c) 无改善而 (b) 也无改善，则正序确实不缺上下文，论文的因果诊断被支持。</li><li><strong>成本</strong>：三次推理 × 128 条 prompt，单卡数小时。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>第一击：一个数值上的异常本身就在质疑因果解释。</strong> 如果闪烁完全源于「倒序块首缺失因果过去」，那么一个完美的过去代理最多把倒序 inter-block FR 恢复到<strong>正序的水平</strong>，即 1.15。但 UniTemp 的倒序 inter FR 是 <strong>1.07，明显优于正序的 1.13–1.17</strong>。倒序比正序还平滑，这不是「修复了不对称」，而是「引入了正序没有的额外平滑」。最自然的解释就是块重叠——正序生成没有重叠，倒序带锚点的有。§10 的实验可以直接判定。</p><p><strong>第二击：inbetween 评测的参照系。</strong> 该实验的「真值」是 <strong>Wan2.1-T2V-14B 生成的视频</strong>，而 Wan2.1-14B 正是 UniTemp 的蒸馏教师（Stage-1 的 ODE 轨迹与 Stage-2 的 real score 网络都来自它）。用教师的输出作为 FID/FVD 的参考分布，会系统性偏袒从该教师蒸馏出的学生。同时条件设置也不对称：两个基线只支持单端<strong>单帧</strong>条件（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">8</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">69</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>），UniTemp 拿到每端 <strong>3 个 latent</strong>（头 9 帧、尾 12 帧）；而且 UniTemp 直接解码真值条件 latent 而不重新生成它们，Head 一致性 99.52 几乎是免费的。这三点叠加后，「FVD 25.00 最好」这一结论的可比性大打折扣。一个干净的对照是：让 UniTemp 也只用单帧条件、并同样重新生成条件帧，再比 FID/FVD。</p><p><strong>第三击：双端 sink 的性质被表述得过于正面。</strong> 正序模式下的「未来 sink」并不是真正的未来内容，而是<strong>已生成的第二个块经 RoPE 重索引搬到未来位置</strong>的副本。这等于强迫整段视频反复对齐同一段内容两次，其后果在表 3 里一目了然：dynamic degree 从 81.25/92.97/87.50 塌到 46.80/44.50/44.50。论文把它描述成「控制动态-一致性权衡」是准确的，但读者容易把「100s subject consistency 97.30 全表最高」与「dynamic degree 高」当成同时成立——它们分属两个不同的配置。</p><p><strong>第四击：正序的净收益接近零。</strong> 表 8 显示 UniTemp-Forward 在七个质量维度中有六个略差于 Self-Forcing，Total 的 +0.39 几乎全部来自 dynamic degree 的 +16.67。而 dynamic degree 是 VBench 里唯一一个「越大越好但与一致性天然对冲」的维度。因此「统一训练不损失正序性能」这一结论，在按维度拆开后更接近「用一致性换动态度」。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：UniTemp 承认了问题的根源在 tokenizer（因果 VAE 与教师模型都天然带正向偏置，锚点只是缓解而非消除），却把修补放在<strong>生成器</strong>这一侧——代价是每个新骨干都要重新做一次双向蒸馏（16 + 3 小时 × 64 卡），而且倒序吞吐永久损失约 37%。这是一个作用点与病因不匹配的修法。</p><p><strong>新的 framing</strong>：不修生成器，也不重训 VAE，而是学一个<strong>latent 到 latent 的方向对称化算子</strong>。因果 VAE 编码出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 可以看成「内容 + 一段被烤进去的过去上下文」。如果能学一个小的双射 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>，把因果 latent 序列映到一个方向对称的编码空间、再映回来，那么任何自回归视频模型都可以在对称空间里以任意顺序生成，最后用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span></span> 转回因果 latent 交给<strong>冻结的原始解码器</strong>。这把「任意顺序生成」从每个模型都要重做一遍的训练问题，变成一个一次性的、与生成器无关的表示问题。</p><p><strong>可借鉴的相邻领域工具</strong>：语音编解码里的「latent adapter」（在冻结 codec 之上学一层可逆映射以改变其性质）；归一化流与可逆网络提供了严格双射的架构；等变/对称表示学习给出了如何把「时间反演」显式作为群作用来约束表示；此外，图像 codec 里的渐进式重排序（把因果扫描顺序转成方向无关的多分辨率表示）是同构的先例。</p><p><strong>第一个实验长什么样</strong>：完全不碰生成器。取一批真实视频，用冻结的 Causal 3D VAE 编码得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>；训练一个小的 latent-to-latent Transformer <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>（几十 M 参数），目标是让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mopen">({</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">})</span></span></span></span> 在<strong>时间反演</strong>下等变，同时保证 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span></span> 重建原 latent 的误差可忽略。评价指标直接用本文提出的 FR：把 latent 序列<strong>倒序</strong>送进 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>、反演、再用冻结解码器解码，测 inter/intra-block FR。若不动生成器就能把倒序 FR 压到 1.0 附近，说明因果偏置确实是纯表示层问题，UniTemp 那一整套双向蒸馏可以被一个通用适配层替代；若压不下去，则说明偏置还牵涉解码器的非线性，那本身也是一个比原论文更精确的诊断结论。</p>',61)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
